#include <iostream>
#include <vector>
#include <atcoder/dsu>

int main() {
    using namespace std;

    unsigned N, M;
    cin >> N >> M;

    vector<vector<unsigned>> edge(N);
    for (unsigned i = 0; i < M; i++) {
        unsigned a, b;
        cin >> a >> b;
        edge[--a].push_back(--b);
        edge[b].push_back(a);
    }

    // 現在の連結成分数
    unsigned connected_components = 0;
    // これまで見た頂点のいずれかと隣接しているか
    vector<bool> already_connected(N);
    // 消すべき頂点の個数 = これまでに見た頂点と隣接している、まだ見ていない頂点の個数
    unsigned to_be_erased = 0;

    // 連結成分を管理する
    atcoder::dsu union_find(N);

    for (unsigned i = 0; i < N; i++) {
        // 頂点 i からなる連結成分を追加
        ++connected_components;
        // ここまでに見た頂点と隣接しているなら、
        if (already_connected[i]) {
            // 消すべき頂点が 1 つ減る
            --to_be_erased;
        }

        for (const auto j : edge[i])
            if (j < i) { // これまでに見た頂点側への辺なら、それを結ぶ
                // 異なる連結成分を結ぶ辺があれば、連結成分数が 1 つ減る
                if (!union_find.same(i, j)) {
                    union_find.merge(i, j);
                    --connected_components;
                }
            } else { // まだ見ていない頂点側への辺なら、フラグを立てる
                // これまで隣接したことがなかった頂点なら、消すべき頂点の個数が増える
                if (!already_connected[j])
                    ++to_be_erased;
                already_connected[j] = true;
            }

        // 番号が i より大きい頂点を全部消したときに連結なら、消すべき頂点を全部消すことで目標を達成できる
        if (connected_components == 1)
            cout << to_be_erased << '\n';
            // そうでないなら、不可能
        else
            cout << -1 << '\n';
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;
#include <atcoder/dsu>

int main() {
	int n, m;
	cin >> n >> m;

	vector<vector<int>> edges(n);
	while (m--) {
		int u, v;
		cin >> u >> v;
		u--, v--;
		edges[u].push_back(v);
		edges[v].push_back(u);
	}

	atcoder::dsu uf_small(n), uf_large(n);

	for (int i = 0; i < n; i++) {
		for (auto j : edges[i]) (j < i ? uf_small : uf_large).merge(i, j);
		cout << (uf_small.size(i) == i + 1 ? uf_large.size(i) - (i + 1) : -1) << "\n";
	}
}
